def mascarar_documento(doc):
    s = ''.join(ch for ch in doc if ch.isdigit())
    if len(s) == 11:
        # CPF: manter XXX.XXX.XXX-XX -> mascarar primeiro 3 e últimos 2
        return '***.' + s[3:6] + '.' + s[6:9] + '-**'
    if len(s) == 16:
        return '**** **** **** ' + s[-4:]
    return doc  # se formato desconhecido, devolve original
